function ChooseClasses({classes,value,onChange}) { return <fieldset><legend>Classes</legend><div className="tp-checks">{classes.map(c=><label key={c.id}><input type="checkbox" checked={value.includes(c.id)} onChange={e=>onChange(e.target.checked?[...value,c.id]:value.filter(id=>id!==c.id))}/>{c.name}</label>)}</div></fieldset> }

const TeacherStudent=memo(function TeacherStudent({student:s}) {
  return <DeferredDetails className="cl-card tw-student" summary={<><span className="tw-student-avatar">{s.name.slice(0,1).toUpperCase()}</span><span><strong>{s.name}</strong><small>@{s.username} · {s.tests.length} tests</small></span><span className="tw-student-id">OMR ID <b>{formatOmrId(s.id)}</b></span></>}>{s.tests.length?<div className="cl-table-scroll"><table className="cl-table"><thead><tr><th>Test</th><th>Mode</th><th>Score</th><th>Accuracy</th></tr></thead><tbody>{s.tests.map((t,i)=><tr key={i}><td>{t.assignment_id?<Link to={`/teacher?report=${t.assignment_id}`}>{t.title}</Link>:t.title}</td><td><span className="cl-pill">{t.mode==='offline'?'Classroom':'Online'}</span></td><td>{t.result.score??'Pending'}{t.result.max_score!=null?` / ${t.result.max_score}`:''}</td><td>{t.result.accuracy==null?'—':`${t.result.accuracy}%`}</td></tr>)}</tbody></table></div>:<p>No test results yet. Assign a paper to this student’s class to get started.</p>}</DeferredDetails>
})

export function TeacherStudents() {
  const load=useLoad('/teacher/students'),[query,setQuery]=useState(''),[downloadError,setDownloadError]=useState(''),[downloading,setDownloading]=useState(false)
  async function csv(){setDownloading(true);setDownloadError('');try{await downloadTeacherFile('/api/teacher/students.csv','class-results.csv')}catch(e){setDownloadError(e.message)}finally{setDownloading(false)}}
  const studentQuery=useDeferredValue(query.trim().toLowerCase())
  const students=useMemo(()=>(load.data?.students||[]).filter(s=>`${s.name} ${s.username} ${formatOmrId(s.id)}`.toLowerCase().includes(studentQuery)),[load.data?.students,studentQuery])
  return <div className="tw-students"><div className="tw-toolbar"><SearchField className="tw-search" label="Find a student" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find by name, username or OMR ID…"/><span className="cl-pill">{load.data?.students.length??'—'} students</span><button className="btn btn-secondary" disabled={downloading||!load.data?.students.length} onClick={csv}>{downloading?'Preparing export…':'Export results CSV'}</button></div><ErrorMessage error={downloadError}/><LoadState {...load}/><p className="tw-scope-note">Your class results only. Each student’s private study activity stays private.</p><div className="tw-student-list">{students.map(s=><TeacherStudent key={s.id} student={s}/>)}</div>{load.data&&!students.length&&<Empty title={query?'No matching students':'Invite your first students'}>{query?'Try another name, username or OMR ID.':<>Share a class join link so students appear here.<Link className="btn btn-primary" to="/teacher?tab=classes">Open classes<ArrowRight size={15}/></Link></>}</Empty>}</div>
}

